#include "independent_paths.hpp"
I power(I a,int n){I v=1;while(n--)v*=a;return v;}
I minimum_strong(int n){if(n%3==0)return 3*power(5,(n-3)/3);if(n%3==1)return power(5,(n-1)/3);return 9*power(5,(n-5)/3);}
std::vector<I>reduced_min(41,I(1)<<60);
int S(int t){int best=0;for(int n=3;n<=40;++n)if(minimum_strong(n)<=I(t))best=n;return best;}
int R(int t){int best=0;for(int n=3;n<=40;++n)if(reduced_min[n]<=I(t))best=n;return best;}
int K(int B,int s){int best=-1;for(int q=1;q<=std::gcd(B,s);++q)if(B%q==0&&s%q==0&&S(B/q)>=4)best=std::max(best,S(B/q)-1+R(q));return best;}
G subset(const G&a,const std::vector<int>&v){G b(v.size());for(int i=0;i<(int)v.size();++i)for(int j=0;j<(int)v.size();++j)if(a[v[i]]>>v[j]&1)b[i]|=1u<<j;return b;}
G edge(G a){int n=a.size();a[0]|=1u<<n;a.push_back(((1u<<n)-1)^1u);return a;}
std::vector<std::vector<int>>scc(const G&a){int n=a.size();std::vector<unsigned>reach(n);for(int r=0;r<n;++r){std::vector<int>todo{r};reach[r]=1u<<r;for(int k=0;k<(int)todo.size();++k){int u=todo[k];for(int v=0;v<n;++v)if((a[u]>>v&1)&&!(reach[r]>>v&1)){reach[r]|=1u<<v;todo.push_back(v);}}}std::vector<std::vector<int>>ans;unsigned seen=0;for(int i=0;i<n;++i)if(!(seen>>i&1)){std::vector<int>part;for(int j=0;j<n;++j)if((reach[i]>>j&1)&&(reach[j]>>i&1)){part.push_back(j);seen|=1u<<j;}ans.push_back(part);}return ans;}
int main(){reduced_min[0]=1;for(int n=3;n<=40;++n)for(int k=3;k<=n;++k)if(reduced_min[n-k]<(I(1)<<60))reduced_min[n]=std::min(reduced_min[n],minimum_strong(k)*reduced_min[n-k]);for(int n=3;n<=40;++n){I closed=n==5?9:n%3==0?power(3,n/3):n%3==1?5*power(3,(n-4)/3):25*power(3,(n-8)/3);need(reduced_min[n]==closed,"reduced minimum partition formula");}
 int total=0,positive=0,equal=0;std::vector<int>levels;for(int n=1;n<=6;++n){int pos=0;for(unsigned bits=0;bits<(1u<<(n*(n-1)/2));++bits){G a(n);int bit=0;for(int i=0;i<n;++i)for(int j=i+1;j<n;++j,++bit)if(bits>>bit&1)a[i]|=1u<<j;else a[j]|=1u<<i;auto p=profile(a,0);int B=p.h+p.L-p.s,s=p.s;++total;need(hp(edge(a))==I(B),"literal edge identity");if(!s)continue;++pos;++positive;auto components=scc(a);std::vector<int>core,keep;I q=1;for(auto c:components){if(std::find(c.begin(),c.end(),0)!=c.end()){core=c;keep.insert(keep.end(),c.begin(),c.end());}else{for(int v:c)need(a[0]>>v&1,"root initial component");if(c.size()>1){keep.insert(keep.end(),c.begin(),c.end());q*=hp(subset(a,c));}}}std::sort(keep.begin(),keep.end());G u=subset(a,keep),c=subset(a,core);auto cp=profile(c,0),up=profile(u,0);need(q*cp.s==p.s&&q*cp.h==p.h&&q*cp.L==p.L,"exact SCC coordinates");need(up.s==p.s&&up.h+up.L-up.s==I(B),"induced same pair");need((B==s)==(core.size()==1),"singleton boundary");if(B==s){++equal;need(int(u.size())<=1+R(B),"equal bound");}else{need(B>s&&strong(edge(c)),"strict strong extension");need(hp(edge(c))==I(B)/q,"strong extension count");need(K(B,s)>=int(u.size())&&K(B,s)<=R(B)-1,"both strict bounds");for(auto part:scc(edge(u)))need(part.size()>=3,"no singleton in extended reduced source");int lg=0;for(int z=B;z>=2;z/=2)++lg;need(int(u.size())<=s+1+lg,"same representative elementary bound");}}levels.push_back(pos);}
 std::vector<std::vector<int>>table(2);for(int r=1;r<=2;++r)for(int j=0;j<=8;++j)table[r-1].push_back(K(137-2*j,r+3*j));need(table==std::vector<std::vector<int>>{{9,9,9,9,9,9,9,8,8},{9,10,9,9,9,9,10,8,8}},"18 caps");int arith=0;for(int B=1;B<=10000;++B)for(int s=1;s<=26;++s)if(B>s){int k=K(B,s);if(k>=0)need(k<=R(B)-1,"universal K versus reduced cap");++arith;}
 std::cout<<"{\"status\":\"PASS\",\"labeled_root_zero_graphs\":"<<total<<",\"positive_start_graphs\":"<<positive<<",\"equal_boundary_graphs\":"<<equal<<",\"positive_by_order\":[";for(int i=0;i<6;++i)std::cout<<(i?",":"")<<levels[i];std::cout<<"],\"reduced_partition_orders\":40,\"arithmetic_pairs\":"<<arith<<",\"base137_caps\":[[9,9,9,9,9,9,9,8,8],[9,10,9,9,9,9,10,8,8]],\"maximum_base137_cap\":10,\"F8\":\"OPEN\"}\n";}
